// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);

        ReentrantCaller attacker = new ReentrantCaller(c);
        vm.deal(address(attacker), 1 ether + amount);

        vm.prank(address(attacker));
        c.Deposit{value: 1 ether + amount}();

        ReentrantCaller.AttackKind kind = ReentrantCaller.AttackKind.RECORD_BALANCE;
        attacker.setAttack(kind, amount);

        try attacker.attack(amount) {
            // observed balance must be the post-subtraction value
        } catch {
            // reference may revert on failed re-entrant inner call; fall through
        }

        uint256 paidOut = 0;
        if (attacker.attacked()) {
            if (attacker.innerOk()) {
                paidOut = amount;
            }
        }

        assertTrue(attacker.observedBalance() == 1 ether + amount - paidOut);
    }

    receive() external payable {}
}

contract ReentrantCaller {
    PrivateBank private c;
    bool private entered;
    uint256 public observedBalance;
    bool public attacked;
    bool public innerOk;

    enum AttackKind { RECORD_BALANCE }
    AttackKind private kind;
    uint256 private innerAmount;

    constructor(PrivateBank _c) {
        c = _c;
    }

    function setAttack(AttackKind _kind, uint256 _amt) external {
        kind = _kind;
        innerAmount = _amt;
    }

    function attack(uint256 amt) external {
        c.CashOut(amt);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            if (kind == AttackKind.RECORD_BALANCE) {
                observedBalance = c.balances(address(this));
            }
            bool ok; try c.CashOut(innerAmount) { ok = true; } catch { ok = false; }
            innerOk = ok;
        }
        attacked = true;
    }
}
